const body = $input.item.json.body;

// Extract voucher data
const companyId = body.companyId;
const voucherId = body.voucherId;
const header = body.header;
const lines = body.lines || [];
const summary = body.summary || {};

// Build text for embedding
const textParts = [
  `Phiếu số: ${header.voucherNumber}`,
  `Ngày: ${header.date}`,
  `Diễn giải: ${header.description || 'Không có'}`,
  ``,
  `Chi tiết:`,
];

// Add line items
lines.forEach((line, index) => {
  textParts.push(
    `${index + 1}. Tài khoản ${line.accountCode} - ${line.accountName}: ` +
    `Nợ ${line.debit.toLocaleString('vi-VN')} - Có ${line.credit.toLocaleString('vi-VN')}`
  );
  if (line.description) {
    textParts.push(`   Diễn giải: ${line.description}`);
  }
});

// Add summary
textParts.push(
  ``,
  `Tổng cộng:`,
  `Tổng nợ: ${summary.totalDebit.toLocaleString('vi-VN')} VND`,
  `Tổng có: ${summary.totalCredit.toLocaleString('vi-VN')} VND`
);

const embeddingText = textParts.join('\n');

// Prepare metadata
const metadata = {
  company_id: companyId.toString(),
  voucher_id: voucherId,
  voucher_number: header.voucherNumber,
  date: header.date,
  description: header.description || '',
  total_debit: summary.totalDebit,
  total_credit: summary.totalCredit,
  line_count: lines.length
};

return {
  json: {
    text: embeddingText,
    metadata: metadata,
    vectorId: `voucher_${voucherId}`,
    namespace: `company-${companyId}`
  }
};

return [
  {
    json: {
      success: true,
      vectorId: $input.item.json.vectorId,
      namespace: $input.item.json.namespace,
      message: 'Voucher embedded successfully'
    }
  }
];

return [
  {
    json: {
      success: false,
      error: 'Invalid webhook secret',
      message: 'Authentication failed'
    }
  }
];

const error = $input.item.json.error || $input.item.json.message || 'Unknown error';

return [
  {
    json: {
      success: false,
      error: error,
      message: 'Failed to process embedding',
      timestamp: new Date().toISOString()
    }
  }
];
